import adsk.core, adsk.fusion, json
def pt(x,y): return adsk.core.Point3D.create(x/10.0,-y/10.0,0)
def ring_sk(root,name,ring):
    sk=root.sketches.add(root.xYConstructionPlane); sk.name=name
    ls=sk.sketchCurves.sketchLines
    for a,b in zip(ring,ring[1:]): ls.addByTwoPoints(pt(a[0],a[1]),pt(b[0],b[1]))
    return sk
def info(sk):
    out=[] 
    for i in range(sk.profiles.count):
        p=sk.profiles.item(i); bb=p.boundingBox; out.append([i,p.areaProperties().area,[[bb.minPoint.x,bb.minPoint.y],[bb.maxPoint.x,bb.maxPoint.y]],p.profileLoops.count])
    return out
def run(_context):
    app=adsk.core.Application.get(); doc=app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
    des=adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType')); root=des.rootComponent
    data=json.load(open('/Users/daiki/Projects/sage60/pcb/mx_plate/gasket_v1/mx_plate_gasket_geometry.json')); ring=data['rings_pcb_mm'][0]
    src=ring_sk(root,'SRC',ring); prof=src.profiles.item(0); loop=prof.profileLoops.item(0); oc=adsk.core.ObjectCollection.create()
    for i in range(loop.profileCurves.count): oc.add(loop.profileCurves.item(i).sketchEntity)
    bb=prof.boundingBox; res=src.offset(oc,adsk.core.Point3D.create(bb.minPoint.x-1,bb.minPoint.y-1,0),0.2)
    out=ring_sk(root,'OUT',ring[:2]+ring[0:1]) if False else root.sketches.add(root.xYConstructionPlane); out.name='OUT'
    projected=out.project2([e for e in res],False)
    print(json.dumps({'res':res.count,'projected':len(projected),'info':info(out)})); doc.close(False)
